async function loadMypageSummary() {
  const safeFixture = getSafeAccountStateFixture();
  if (safeFixture) {
    applySummary(safeFixture);
    return;
  }
  if (typeof apiFetch !== "function" || typeof isLoggedIn !== "function" || !isLoggedIn()) return;
  // #266 — fetch 시작 직후 loading 상태로 전환. 두 fetch 가 동시에 실패하면 error 표시.
  applyDebutLoading();
  // #501 — debut API 오류 상태 캡처. 501 = endpoint 미준비, 404 = 신청 없음(정상).
  let debutApiErrorStatus = null;
  const [summary, latestResponse] = await Promise.all([
    apiFetch("/api/v1/me/summary", { auth: true }).catch(() => null),
    apiFetch("/api/v1/me/debut-applications/latest", { auth: true, throwOnError: true })
      .catch(err => { debutApiErrorStatus = err?.status || 0; return null; })
  ]);
  const latestApplication = latestResponse?.latestApplication || latestResponse?.application || latestResponse;
  if (summary && latestApplication && typeof latestApplication === "object" && Object.keys(latestApplication).length) {
    summary.debut = summary.debut || {};
    summary.debut.latestApplication = latestApplication;
  }
  if (summary) {
    applySummary(summary);
    // #501 — API endpoint 미준비(501)이면 debut 섹션만 "준비 중"으로 override.
    // 404는 신청 없음(정상 응답)이므로 applySummary의 "신청 전" 상태를 그대로 유지.
    if (debutApiErrorStatus === 501) applyDebutApiNotReady();
    return;
  }
  // #266 — summary fetch 자체가 실패 → 사용자가 신청한 적이 있는지 알 수 없으므로
  // "신청 전" 으로 misleading 하지 않고 error 상태로 표시.
  applyDebutError();
}

