changes.before:
async function loadMypageSettings() {
  if (typeof apiFetch !== "function" || typeof isLoggedIn !== "function" || !isLoggedIn()) return;
  const data = await apiFetch("/api/v1/me/settings", { auth: true }).catch(() => null);
  const settings = data?.settings || data || {};
  const values = {
    mypageLocale: settings.locale,
    mypageTimezone: settings.timezone,
    mypageActivityNotifications: settings.activityNotifications,
    mypageMarketingNotifications: settings.marketingOptIn ?? settings.marketingNotifications,
    mypageFeedNotifications: settings.feedNotifications,
    mypageEmailNotifications: settings.emailNotifications
  };
  Object.entries(values).forEach(([id, value]) => {
    const el = $(id);
    if (!el || value === undefined || value === null) return;
    if (el.type === "checkbox") el.checked = !!value;
    else el.value = value;
  });
}

